//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::libm::atanh`; the
//! native twin is `benches/native/Bench/LibmAtanh.lean`.

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::{float, libm};
use lean_runtime_bench::{run, step, SEED};

#[allow(unused_variables)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0.0f64);
    for _ in 0..n {
        x = step(x);
        acc += libm::atanh(
            (-0.9990234375 + ((x >> 11) as f64 * (1.0 / 9007199254740992.0)) * 1.998046875),
        );
    }
    float::to_bits(acc) as u64
}

fn main() {
    run(|| (), kernel)
}
